def label(path,es):
 if path in PAGES:return PAGES[path]['es' if es else 'en']['name']
 return next(names[int(es)] for slug,names,_,_ in CATEGORIES if slug==path)

def children(path):return [k for k,v in PAGES.items() if v['parent']==path]
def artbox(kind):return '<div class="svc-art"><pre aria-hidden="true">'+escape(ascii_art(kind))+'</pre><span class="s-mono">[ DESIGN + CODE + CARE ]</span></div>'
def link(path,es,name=None):return '<a class="svc-sub-link" href="'+('/es' if es else '')+'/services/'+path+'/">'+escape(name or label(path,es))+'<span aria-hidden="true">↗</span></a>'

def detail(path,es):
 lang='es' if es else 'en';p='/es' if es else '';entry=PAGES[path];c=entry[lang];parent=entry['parent']
 crumbs=f'<a href="{p}/services/">'+('Servicios' if es else 'Services')+'</a>'
 if parent:crumbs+=' <span aria-hidden="true">/</span> '+f'<a href="{p}/services/{parent}/">{label(parent,es)}</a>'
 crumbs+=' <span aria-hidden="true">/</span> <span aria-current="page">'+c['name']+'</span>'
 title='Qué incluye' if es else 'What is included';before='Qué necesito de ti' if es else 'What I need from you'
 body=f'<main id="main" class="svc-detail"><div class="s-container"><nav class="svc-breadcrumb" aria-label="Breadcrumb">{crumbs}</nav><section class="svc-hero"><div><p class="s-eyebrow">{escape(c["name"].upper())}</p><h1>{c["h1"]}</h1><p class="svc-lead">{c["lead"]}</p><div class="svc-actions"><a class="s-button" href="{p}/contact/?service={path}">'+('Hablemos de este proyecto' if es else 'Discuss this project')+'<span aria-hidden="true">↗</span></a><a class="s-text-link" href="#included">'+title+' ↓</a></div></div>'+artbox(entry['kind'])+'</section>'
 body+='<section class="svc-fit"><p class="s-eyebrow">'+('CUÁNDO ENCAJA' if es else 'WHEN IT FITS')+'</p><p>'+c['fit']+'</p></section>'
 body+='<section class="svc-delivery" id="included"><div><h2>'+title+'</h2><ul>'+''.join('<li>'+i+'</li>' for i in c['items'])+'</ul></div><aside><h2>'+before+'</h2><ul>'+''.join('<li>'+i+'</li>' for i in c['inputs'])+'</ul></aside></section>'
 body+='<section class="svc-scope"><h2>'+('El alcance, claro desde el principio.' if es else 'A clear scope from the beginning.')+'</h2><p>'+c['scope']+'</p></section>'
 steps=[('Revisamos','Acordamos el objetivo, el contenido y las funciones.'),('Definimos','La propuesta concreta las páginas, entregables y revisiones.'),('Implementamos','Desarrollo, pruebas y una entrega con próximos pasos claros.')] if es else [('Review','We agree on the goal, content and functionality.'),('Define','The proposal sets out pages, deliverables and reviews.'),('Implement','Development, checks and a handover with clear next steps.')]
 body+='<section class="svc-how"><h2>'+('Cómo trabajamos' if es else 'How we work')+'</h2><div>'+''.join(f'<article><span class="s-mono">0{i+1}</span><h3>{name}</h3><p>{desc}</p></article>' for i,(name,desc) in enumerate(steps))+'</div></section>'
 if c.get('proof'):
  n,u=c['proof'];body+='<p class="svc-evidence">'+('Explora un directorio de mi portafolio: ' if es else 'Explore a directory in my portfolio: ')+f'<a class="s-text-link" href="{p}{u}">{n} ↗</a></p>'
 if c.get('article'):body+=f'<p class="svc-evidence"><a class="s-text-link" href="{p}/blog/wordpress-to-webflow-migration/">'+('¿Conviene migrar de WordPress a Webflow?' if es else 'Should you migrate from WordPress to Webflow?')+' ↗</a></p>'
 body+='<section class="svc-question"><h2>'+c['question']+'</h2><p>'+c['answer']+'</p></section>'
 body+='<section class="svc-related"><p class="s-eyebrow">'+('OTRAS PIEZAS DEL PROYECTO' if es else 'OTHER PARTS OF THE PROJECT')+'</p><div>'+''.join(link(x,es) for x in c['related'])+'</div></section></div>'
 body+=f'<section class="s-closing"><div class="s-container"><p class="s-eyebrow">'+('EMPECEMOS CON TU IDEA' if es else 'START WITH YOUR IDEA')+'</p><h2>'+('¿Lo construimos?' if es else 'Shall we build it?')+f'</h2><p>'+('Comparte tu sitio actual, qué quieres mejorar y las fechas que tienes en mente.' if es else 'Share your current website, what you want to improve and the dates you have in mind.')+f'</p><a class="s-button" href="{p}/contact/?service={path}">'+('Hablemos del proyecto' if es else 'Let’s discuss the project')+' ↗</a></div></section></main>'
 return body

def build():
 for es in (False,True):
  p='/es' if es else '';lang='es' if es else 'en'
  template=(DIST/('es/services/webflow-development/index.html' if es else 'services/webflow-development/index.html')).read_text()
  # New solutions get their own useful page, metadata and breadcrumb hierarchy.
  for path,entry in PAGES.items():
   c=entry[lang];text=template.replace('/services/webflow-development/','/services/'+path+'/')
   text=re.sub(r'<main\b.*?</main>',lambda m:detail(path,es),text,count=1,flags=re.S)
   title=c['name']+' | Laura Ortega · Pancratzia'
   text=re.sub(r'<title>.*?</title>','<title>'+escape(title)+'</title>',text)
   for attr,value in [('name="description"',c['lead']),('property="og:description"',c['lead']),('name="twitter:description"',c['lead']),('property="og:title"',title),('name="twitter:title"',title)]:
    text=re.sub(r'<meta '+attr+r' content="[^"]*">','<meta '+attr+' content="'+escape(value,quote=True)+'">',text)
   text=re.sub(r'<script type="application/ld\+json">.*?</script>','',text,flags=re.S)
   url=ORIGIN+p+'/services/'+path+'/'
   schema={'@context':'https://schema.org','@type':'Service','name':c['name'],'description':c['lead'],'url':url,'provider':{'@type':'Person','name':'Laura Ortega','url':ORIGIN+'/about/'}}
   text=text.replace('</head>','<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script></head>')
   dest=DIST/(p+'/services/'+path+'/index.html').lstrip('/');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text)
  # Keep existing category detail, pricing terms and established URLs intact.
  for slug,names,desc,kind in CATEGORIES:
   if slug in PAGES:continue
   file=DIST/(p+'/services/'+slug+'/index.html').lstrip('/');text=file.read_text()
   text=re.sub(r'<div class="service-photo">.*?</div>',lambda m:artbox(kind),text,flags=re.S)
   subtree=children(slug)
   if subtree:
    section='<section class="svc-specialties s-container"><p class="s-eyebrow">'+('ENCUENTRA TU SOLUCIÓN' if es else 'FIND YOUR SOLUTION')+'</p><h2>'+('Un servicio para cada necesidad.' if es else 'A service for the job you need.')+'</h2><div>'+''.join(link(x,es) for x in subtree)+'</div></section>'
    if 'svc-specialties' not in text:text=text.replace('<section class="closing',section+'<section class="closing',1)
   file.write_text(text)
  # Main directory groups broad services and links to specific scopes.
  hubfile=DIST/(p+'/services/index.html').lstrip('/');text=hubfile.read_text()
  intro='Diseño, desarrollo y cuidado de tu sitio. Encuentra el área y la solución que encajan con lo que necesitas.' if es else 'Design, development and ongoing care. Find the area and the specific service that fit your next project.'
  main=f'<main id="main" class="svc-hub"><div class="s-container"><section class="svc-hub-heading"><p class="s-eyebrow">'+('SERVICIOS / DE LA IDEA AL SITIO' if es else 'SERVICES / FROM IDEA TO WEBSITE')+'</p><h1>'+('¿Qué necesita<br><em>tu próximo capítulo?</em>' if es else 'What does your<br><em>next chapter need?</em>')+'</h1><p>'+intro+'</p><div class="svc-jump">'+''.join('<a href="#'+slug+'">'+names[int(es)]+'</a>' for slug,names,_,_ in CATEGORIES)+'</div></section><div class="svc-hub-grid">'
  for i,(slug,names,desc,kind) in enumerate(CATEGORIES):
   main+=f'<article class="svc-category" id="{slug}"><div class="svc-category-top"><span class="s-mono">0{i+1} /</span><pre aria-hidden="true">{escape(ascii_art(kind))}</pre></div><h2>{names[int(es)]}</h2><p>{desc[int(es)]}</p>'+link(slug,es,'Ver el servicio' if es else 'Explore service')
   sub=children(slug)
   if sub:main+='<div class="svc-child-links">'+''.join(link(x,es) for x in sub)+'</div>'
   main+='</article>'
  main+='</div><section class="svc-help"><div><p class="s-eyebrow">'+('¿NO SABES POR DÓNDE EMPEZAR?' if es else 'NOT SURE WHERE TO START?')+'</p><h2>'+('Cuéntame lo que quieres mejorar.' if es else 'Tell me what you want to improve.')+'</h2><p>'+('No necesitas elegir una herramienta antes de conversar. Comparte tu web o tu idea y definimos el alcance.' if es else 'You do not need to choose a tool before we talk. Share your website or idea and we can define the scope.')+f'</p></div><div><a class="s-button" href="{p}/contact/">'+('Hablemos del proyecto' if es else 'Let’s discuss the project')+f' ↗</a><a class="s-text-link" href="{p}/pricing/">'+('Ver paquetes y precios iniciales' if es else 'See packages and starting prices')+' ↗</a></div></section></div></main>'
  text=re.sub(r'<main\b.*?</main>',lambda m:main,text,count=1,flags=re.S)
  text=re.sub(r'<title>.*?</title>','<title>'+('Servicios de Diseño y Desarrollo Webflow' if es else 'Webflow Design & Development Services')+' | Pancratzia</title>',text)
  hubfile.write_text(text)
 # Share the stylesheet across the service family, including new descendants.
 for file in DIST.rglob('*.html'):
  if '/services/' not in '/'+str(file.relative_to(DIST)):continue
  t=file.read_text()
  if '/services-studio.css' not in t:t=t.replace('</head>','<link rel="stylesheet" href="/services-studio.css"></head>')
  file.write_text(t)

if __name__=='__main__':build()
